import urllib.request
urls=['https://www.fpbase.org/api/proteins/','https://www.fpbase.org/api/protein/','https://fpbase.org/api/proteins/','https://www.fpbase.org/api/']
for u in urls:
 try:
  r=urllib.request.urlopen(u,timeout=30)
  print(u, r.status, r.headers.get('content-type'))
  print(r.read(1000).decode('utf-8','replace'))
 except Exception as e: print(u,e)
PY

