python - <<'PY'
import urllib.request
for u in ['https://www.fpbase.org/','https://www.fpbase.org/protein/clover/','https://www.fpbase.org/protein/mcherry/','https://www.fpbase.org/api/proteins/?format=json','https://www.fpbase.org/api/proteins.json','https://www.fpbase.org/api/proteins']:
 for ua in ['Mozilla/5.0','curl/8.0','']:
  try:
   req=urllib.request.Request(u,headers={'User-Agent':ua,'Accept':'application/json,text/html,*/*'})
   r=urllib.request.urlopen(req,timeout=20)
   data=r.read(500).decode('utf-8','replace')
   print('OK',u,ua,r.status,r.headers.get('content-type'),data[:100].replace('\n',' '))
   break
  except Exception as e: print('ERR',u,ua,repr(e))
PY

